/* Types */
/**  The selected account (the account manager's header and Account summary tab). */
export type Account = {
	id?: string,
	name?: string,
	currency?: string,
	/**  A demo / paper account: the app shows DEMO, else LIVE. */
	isDemo?: boolean,
	balance?: number | null,
	equity?: number | null,
	unrealizedPnl?: number | null,
	realizedPnl?: number | null,
	marginUsed?: number | null,
	marginFree?: number | null,
	/**  Everything else the broker reports, as label / value rows. */
	values?: AccountValue[],
};

/**  A tab of the broker's own (`pages`): one or more tables whose columns the broker defines. */
export type AccountPage = {
	id: string,
	title: string,
	/**  The tab shows its number of rows, as Positions and Orders do. */
	counter?: boolean,
	tables: AccountPageTable[],
};

export type AccountPageColumn = {
	id: string,
	label: string,
	format?: ColumnFormat,
	/**  Shown once the user picks it in Column setup. */
	hidden?: boolean,
};

export type AccountPageSort = {
	column: string,
	asc?: boolean,
};

export type AccountPageTable = {
	id: string,
	/**  Shown above the table when the page has several. */
	title?: string | null,
	columns: AccountPageColumn[],
	/**  The sort before the user picks one. */
	sort?: AccountPageSort | null,
	/**  Each row: column id → value (null: empty); `id` keys the row when present. */
	rows?: ({ [key in string]: PageCell | null })[],
};

export type AccountRef = {
	id?: string,
	name?: string,
};

export type AccountValue = {
	label?: string,
	value?: string,
	currency?: string | null,
};

/**  One JSON-RPC message for `window` (its label; the other windows ignore it) to answer with `agent_reply` (same id). */
export type AgentRequest = {
	window: string,
	id: number,
	body: string,
};

/**  What Settings shows. */
export type AgentServerStatus = {
	enabled: boolean,
	/**  Listening now. */
	running: boolean,
	port: number,
	token: string,
	/**  The endpoint an agent connects to. */
	url: string,
	/**  Why it isn't listening (port in use…). */
	error: string | null,
};

/**  What a window needs to compile its rules. */
export type AlertEngineInfo = {
	/**
	 *  Per symbol, the time (UNIX seconds) of the last quote evaluated by
	 *  the previous run: the bars to cover start there.
	 */
	previous: { [key in string]: number | null },
};

/**
 *  A rule fired. Every window receives it; the one named `window` delivers
 *  it (log, sound, notification, webhook).
 */
export type AlertFired = {
	window: string,
	ruleId: string,
	price: number | null,
	/**  UNIX seconds. */
	time: number | null,
	barTime: number | null,
	/**  Found by the replay of the bars missed while the app was not running. */
	offline: boolean,
};

/**  The window that runs the alerts changed (the previous one was closed). */
export type AlertLeader = {
	window: string,
};

/**  Current update state, sent to every window on each change. */
export type AppUpdateStatus = {
	state: UpdateState,
	/**  The new version while downloading / ready / installing. */
	version: string | null,
	/**
	 *  The gateway no longer serves this version: market data has stopped
	 *  until the app is updated.
	 */
	updateRequired: boolean,
	/**
	 *  The gateway disabled this copy (gateway#16): its code (install id) to
	 *  quote to support. Market data has stopped.
	 */
	disabled: string | null,
	/**  Why the last check or download failed (state `error`). */
	error: UpdateError | null,
};

/**  The zoom changed (every window updates the value its menu shows). */
export type AppZoomChanged = {
	zoom: number | null,
};

/**
 *  Sent to every window right before the app exits (an update installs, or
 *  Exit in the main menu): write pending settings now, then call
 *  `app_settings_flushed`.
 */
export type BeforeExit = {
	/**  The version about to install; None when the app just quits. */
	update: string | null,
};

/**  The members of one breakdown, largest first. */
export type BreakdownGroup = {
	revenue?: BreakdownRole | null,
	profit?: BreakdownRole | null,
	revenueShare?: BreakdownRole | null,
	members: BreakdownMember[],
};

/**  One segment, product line, country or region, or customer. */
export type BreakdownMember = {
	id: string,
	label: string,
	revenue?: number | null,
	/**  Segments only. */
	profit?: number | null,
	/**  Customers only: the share of revenue as filed (0..1). */
	revenueShare?: number | null,
};

/**  The figures of one filing for one fiscal period. */
export type BreakdownReport = {
	/**  The filing's id (as `list_filings` gives it). */
	accession: string,
	form: string,
	/**  When the filing became public (UTC). */
	accepted: string,
	fy?: number | null,
	/**  Q1-Q4 or FY. */
	fp?: string | null,
	/**  Month end of the period. */
	periodEnd: string,
	/**  3 or 12. */
	months: number,
	/**  A Q4 computed as the year less the first nine months. */
	derived: boolean,
	currency: string,
	totalRevenue?: number | null,
	segments?: BreakdownGroup | null,
	products?: BreakdownGroup | null,
	geography?: BreakdownGroup | null,
	customers?: BreakdownGroup | null,
};

/**  The figure a group's role is read from, and how its members add up. */
export type BreakdownRole = {
	/**  The filed concept (`us-gaap:Revenues`, `ifrs-full:Revenue`, `custom:…`). */
	concept: string,
	/**  The consolidated value. */
	total?: number | null,
	/**
	 *  Members' sum / `total`; above 1 the members mix levels (subtotals,
	 *  intersegment sales, a region and its countries).
	 */
	coverage?: number | null,
};

/**  What the plugin's broker supports; the order ticket and the chart offer only that. */
export type BrokerCapabilities = {
	orderTypes?: OrderType[],
	/**  Take profit / stop loss on a new order. */
	brackets?: boolean,
	/**  Take profit / stop loss on an open position. */
	positionBrackets?: boolean,
	/**  Close part of a position. */
	partialClose?: boolean,
	/**  Modify a working order's price or quantity. */
	modifyOrders?: boolean,
	/**  The broker's own order choices (a product type…), shown as selectors in the order ticket. */
	ticketFields?: TicketField[],
	/**  How long an order stays working (time in force): the order ticket's selector. None: the plugin's own. */
	durations?: OrderDuration[],
	/**
	 *  A stop order may sit on either side of the market (a buy stop below the ask). Without it the app refuses one
	 *  on the wrong side: it would trigger at once.
	 */
	stopOrdersBothSides?: boolean,
	/**  The same for the stop price of a stop limit order. */
	stopLimitOrdersBothSides?: boolean,
	/**
	 *  A limit order may not cross the market (a buy limit above the ask). Without it such an order is sent, as a
	 *  marketable limit, unless its price is more than half the market price away.
	 */
	strictLimitPrice?: boolean,
	/**
	 *  The broker previews an order before it is sent (`broker.previewOrder`: its commission, its margin…): the order
	 *  ticket shows the confirmation page, unless the user turned it off.
	 */
	orderPreview?: boolean,
	/**
	 *  Several exit levels on an order or a position (`exitLevels` on orders, positions and tickets), each a part of
	 *  its quantity with its own take profit and stop loss.
	 */
	exitLevels?: boolean,
	/**  The most exit levels an order or a position takes (8 when left out). */
	maxExitLevels?: number | null,
};

/**
 *  The order book of a ticker the DOM shows (`broker.depth`): the whole book (`snapshot`), or the levels that changed,
 *  a quantity of 0 removing its level.
 */
export type BrokerDepth = {
	ticker: string,
	snapshot?: boolean,
	bids?: DepthLevel[],
	asks?: DepthLevel[],
};

/**  An order notification (`broker.event`): the toasts. */
export type BrokerEvent = {
	/**  "placed" | "executed" | "modified" | "cancelled" | "rejected" */
	kind: string,
	ticker: string,
	side: Side,
	type: OrderType,
	qty: number | null,
	price?: number | null,
	message?: string | null,
};

export type BrokerNotice = {
	timeMs: number | null,
	/**  "info" | "warn" | "error" */
	level: string,
	message: string,
};

/**  An order notification of the active broker (`broker.event`): a toast. */
export type BrokerOrderEvent = {
	event: BrokerEvent,
};

export type BrokerPlugin = {
	id: string,
	name: string,
	connected: boolean,
};

/**  Bid / ask / last of a ticker the order ticket watches (`broker.quote`). */
export type BrokerQuote = {
	ticker: string,
	bid: number | null,
	ask: number | null,
	last: number | null,
};

/**  The plugin's whole account state (`broker.state`), sent again whenever a part changes. */
export type BrokerState = BrokerState_Serialize | BrokerState_Deserialize;

/**  The plugin's whole account state (`broker.state`), sent again whenever a part changes. */
export type BrokerState_Deserialize = {
	/**  The plugin is connected to its broker (logged in). */
	connected?: boolean,
	accounts?: AccountRef[],
	account?: Account | null,
	positionMode?: PositionMode,
	capabilities?: BrokerCapabilities,
	positions?: Position_Deserialize[],
	orders?: Order_Deserialize[],
	executions?: Execution[],
	/**
	 *  The broker's own tabs of the account manager (holdings, funds…), after Trade history. A page that doesn't read
	 *  is left out, not the whole state.
	 */
	pages?: AccountPage[],
};

/**  The plugin's whole account state (`broker.state`), sent again whenever a part changes. */
export type BrokerState_Serialize = {
	/**  The plugin is connected to its broker (logged in). */
	connected: boolean,
	accounts: AccountRef[],
	account: Account | null,
	positionMode: PositionMode,
	capabilities: BrokerCapabilities,
	positions: Position_Serialize[],
	orders: Order_Serialize[],
	executions: Execution[],
	/**
	 *  The broker's own tabs of the account manager (holdings, funds…), after Trade history. A page that doesn't read
	 *  is left out, not the whole state.
	 */
	pages: AccountPage[],
};

/**  The trading side as the window reads it; sent again (`broker-status`) whenever it changes. */
export type BrokerStatus = BrokerStatus_Serialize | BrokerStatus_Deserialize;

/**  The trading side as the window reads it; sent again (`broker-status`) whenever it changes. */
export type BrokerStatus_Deserialize = {
	version: number,
	/**  The enabled broker plugins. */
	brokers: BrokerPlugin[],
	/**  The broker plugin the user connected. */
	active: string | null,
	activeName: string | null,
	/**  The active plugin is connected to the app. */
	pluginConnected: boolean,
	/**  The exchange of the active plugin's own symbols when it is a data plugin too: its symbols trade as they are. */
	dataExchange: string | null,
	/**  The exchanges of a data plugin that serves several (#331): its tickers are whole symbols (`NSE:RELIANCE`). */
	dataExchanges: string[],
	tradingEnabled: boolean,
	/**  Its account, as the plugin last sent it. */
	state: BrokerState_Deserialize | null,
	notices: BrokerNotice[],
};

/**  The trading side as the window reads it; sent again (`broker-status`) whenever it changes. */
export type BrokerStatus_Serialize = {
	version: number,
	/**  The enabled broker plugins. */
	brokers: BrokerPlugin[],
	/**  The broker plugin the user connected. */
	active: string | null,
	activeName: string | null,
	/**  The active plugin is connected to the app. */
	pluginConnected: boolean,
	/**  The exchange of the active plugin's own symbols when it is a data plugin too: its symbols trade as they are. */
	dataExchange: string | null,
	/**  The exchanges of a data plugin that serves several (#331): its tickers are whole symbols (`NSE:RELIANCE`). */
	dataExchanges: string[],
	tradingEnabled: boolean,
	/**  Its account, as the plugin last sent it. */
	state: BrokerState_Serialize | null,
	notices: BrokerNotice[],
};

export type BuildInfo = {
	version: string,
	/**  `YYYY-MM-DD` (UTC). */
	buildDate: string,
};

/**
 *  A single OHLCV candle — the shape returned to the chart for every
 *  resolution (daily, minute, second).
 */
export type Candle = {
	/**
	 *  UTC seconds (lightweight-charts `UTCTimestamp`). Stored as `f64` so
	 *  specta-typescript doesn't reject the export (i64 is forbidden to
	 *  avoid BigInt precision loss); f64 holds exact integers up to 2^53.
	 */
	time: number | null,
	open: number | null,
	high: number | null,
	low: number | null,
	close: number | null,
	volume: number | null,
};

export type Capability = 
/**  Symbols, bars and live ticks (`data.*`). */
"datafeed" | 
/**  An account: positions, orders, executions and order commands (`broker.*`). */
"broker";

/**  One plugin of the catalog (`plugins/catalog.json` of the repository). */
export type CatalogEntry = {
	id: string,
	name: string,
	version: string,
	publisher?: string,
	description?: string,
	provides: Capability[],
	api: number,
	platforms?: string[],
	homepage?: string | null,
	url: string,
	sha256: string,
	/**  The package's minisign signature (base64, as `tauri signer sign` writes it). */
	signature: string,
};

export type Cell = number | null | string;

/**
 *  Per-minute bar (`bar1m` channel, or the polled snapshot) re-emitted to
 *  the chart. One bar per minute per symbol. `time` is the bar's start in **UNIX seconds** so it lines
 *  up with lightweight-charts' UTCTimestamp type and the existing daily +
 *  minute history payloads.
 */
export type ChartAggregate = {
	symbol: string,
	time: number | null,
	open: number | null,
	high: number | null,
	low: number | null,
	close: number | null,
	volume: number | null,
	/**
	 *  Today's full-session daily bar when the transport knows it (the REST
	 *  snapshot poller does; the stream minute bars don't). Lets the frontend
	 *  update the daily-family chart bar exactly — a warm daily load skips
	 *  today's forming bar on purpose (see `fetch_daily_history`) and this is
	 *  what fills it. The Candle's `time` is the snapshot's update stamp; the
	 *  frontend re-buckets it to the daily-bar convention (midnight ET).
	 */
	day: Candle | null,
};

export type Clause = {
	left: string,
	operation: Op,
	right: Operand,
};

/**  How a column's values show. An unknown format shows as text. */
export type ColumnFormat = 
/**  The broker's ticker: a row click shows it on the chart. */
"symbol" | 
/**  "buy" / "sell", shown as Buy / Sell. */
"side" | "qty" | 
/**  On the tick of the row's symbol. */
"price" | 
/**  An amount of the account's currency. */
"money" | 
/**  A signed amount, green or red. */
"pnl" | "percent" | 
/**  A signed percent, green or red. */
"pnlPercent" | "number" | 
/**  UNIX milliseconds, shown as a local date and time. */
"time" | "text";

/**  What the company declares about itself in its filings. */
export type CompanyProfile = {
	/**  Standard industrial classification code ("3571"). */
	sic?: string | null,
	/**  Name of the industry code ("Electronic Computers"). */
	industry?: string | null,
	/**  Broad sector ("Technology", "Life Sciences", "Finance"…). */
	sector?: string | null,
	/**  "large_accelerated", "accelerated", "non_accelerated" or null. */
	filerCategory?: string | null,
	smallerReporting?: boolean,
	emergingGrowth?: boolean,
	/**  State ("DE") or country of incorporation. */
	incorporation?: string | null,
	headquarters?: Headquarters | null,
	listings?: Listing[],
	formerNames?: FormerName[],
};

/**  Symbol `data_status` values. */
export type DataStatus = "streaming" | "delayed_streaming" | "endofday" | 
/**  The provider reported a status we have no mapping for. */
"unknown";

/**  Links arrived for `window`: it takes them with `deep_link_take`. */
export type DeepLinkOpened = {
	window: string,
};

/**  One price level of an order book: the quantity resting at that price, in units. */
export type DepthLevel = {
	price: number | null,
	qty: number | null,
};

/**
 *  A dividend marker: ex-dividend date (UNIX seconds) + cash amount per share,
 *  and the payment date (UNIX seconds) when known.
 */
export type DividendEvent = {
	date: number | null,
	amount: number | null,
	payDate: number | null,
};

/**  One earnings release. */
export type EarningsEvent = {
	/**  Release date (YYYY-MM-DD). */
	date: string,
	/**  "bmo" (before the regular session), "amc" (after it), or null. */
	time?: string | null,
	/**  False when the period had no results announcement (dated by its report). */
	released?: boolean,
	/**  Fiscal period end (YYYY-MM-DD). */
	end: string,
	fy?: number | null,
	fp?: string | null,
	/**  Diluted earnings per share of the quarter. */
	eps?: number | null,
	revenue?: number | null,
};

/**  An economy of the catalog: the Economy tab's country panel. */
export type EconomicCountry = {
	code: string,
	name: string,
	/**  "North America", "Europe", "Asia"… */
	region: string,
};

/**
 *  Bars of one symbol on one interval and session (regular or extended
 *  hours), ascending: (open, close) in UNIX seconds (the last bar of a session
 *  closes with it).
 */
export type EngineGrid = {
	key: string,
	bars: ([number | null, number | null])[],
	/**
	 *  Regular-session intervals (start, end) over the same dates: tell a
	 *  pre- or post-market trade from a regular one. Empty = all regular.
	 */
	regular: ([number | null, number | null])[],
	/**
	 *  Hours (start, end) of the rule's session over the same dates: a quote
	 *  outside them is not read. Empty = always.
	 */
	session?: ([number | null, number | null])[],
	/**
	 *  The session is the extended one: a pre- or post-market trade is read
	 *  (on regular hours it is not: those bars do not move then).
	 */
	extendedHours?: boolean,
};

/**  One rule, compiled by the window. */
export type EngineRule = {
	id: string,
	/**  Full name, uppercased ("NASDAQ:AAPL"). */
	symbol: string,
	/**
	 *  Changes whenever the condition or what it reads changes: the rule's
	 *  evaluation memory is kept only while it stays the same.
	 */
	sig: string,
	/**
	 *  crossing | crossing_up | crossing_down | greater | less | entering |
	 *  exiting | inside | outside | hits_level
	 */
	op: string,
	/**
	 *  What `values` hold: "level" [price], "band" [bound, bound], "position"
	 *  [entry, stop, target], "time" [UNIX seconds].
	 */
	shape: string,
	/**  only_once | once_per_bar | once_per_bar_close | every_time */
	frequency: string,
	/**  UNIX ms after which the rule no longer fires. */
	expiresAt: number | null,
	/**  UNIX ms the rule became active: a replay never starts before it. */
	since: number | null,
	/**  Key of the bars of the rule's interval (`EngineGrid::key`). */
	grid: string,
	/**  Values that hold at any time. */
	values: (number | null)[],
	/**
	 *  Values per bar of the grid (a sloped line, a drawing limited to its
	 *  dates); an empty entry = no value on that bar. Replaces `values`.
	 */
	perBar: ((number | null)[])[] | null,
	/**
	 *  A band without value counts as "outside" (a rectangle outside its
	 *  dates) instead of leaving the condition undecided.
	 */
	absentIsOutside: boolean,
	/**
	 *  A multi-condition alert: the conditions after the first one, each on
	 *  its own grid; the rule fires when all of them hold with the first.
	 */
	and?: EngineRule[],
};

/**  What the credential / plan allows, measured by the provider's probe. */
export type Entitlements = {
	dataStatus: DataStatus,
	/**  The provider's own status word, kept for diagnosis (gateway: "delayed" / "realtime"). */
	rawStatus: string,
	/**  Data delay in seconds (delayed data: 900). */
	delaySec: number,
	historyFloor: HistoryFloor,
	/**
	 *  Live-stream channels the key may subscribe to. `None` until the stream
	 *  probe finishes, or when it failed.
	 */
	stream: StreamCaps | null,
	/**  When the history probe ran (RFC 3339, UTC). */
	checkedAt: string,
};

